var Registry = require("@taf/taf-registry");
var Endpoint = require("@taf/taf-utils").Endpoint;
var TimeProvider = require("@taf/taf-utils").timeProvider;
var AdapterProxy = require("./AdapterProxy.js").AdapterProxy;
var ConsistentHash = require("../util/ConsistentHash");
var fs = require('fs');
var path = require('path');
var Q = require('q');

/////////////////////////////////////////////主控地址管理类/////////////////////////////////////////////////////////////
var EndpointManager = function ($RefObjectProxy, $RefCommunicator, $ObjectName, $SetName, options) {
    this._registry = Registry.New();
    this._objname = $ObjectName;      //_initialize之后为分离之后的servant名字
    this._setname = $SetName;         //SET的名称
    this._worker = $RefObjectProxy;  //ObjectProxy引用
    this._comm = $RefCommunicator; //通信器引用
    this._adapters = [];               //当前服务下所有的通信代理类
    this._hash = 0;                //Hash值
    this._iVnodeNumber = 100;           //一致性哈希，虚拟节点个数
    this._consistentHash = undefined;  //一致性hashring
    this._direct = false;            //是否是直连服务，否则需要走主控查询可用地址+端口
    this._bRequest = false;            //是否正在请求中

    this._iRefreshTime = 0;         //IPList的刷新时间
    this._iRefreshInterval = 60000;     //成功请求非空列表的更新间隔时间，单位毫秒
    this._iActiveEmptyInterval = 10000;     //请求回来活跃列表为空的间隔时间，单位毫秒
    this._iRequestTimeout = 0;         //请求的超时时间(绝对时间) 防止请求回调丢了。一直在正在请求状态
    this._iWaitTime = 5000;      //请求主控的等待时间，单位毫秒
    this._locator = undefined; //主控

    //hash随机开始
    var m = 0;
    var n = 1000;
    this._hash = Math.floor(Math.random() * (m - n)) + n;

    //创建一致性hashring，若要指定虚拟节点个数，可通过这种方式启动hashring功能
    if (options.bEnableConsistentHash) {
        this._consistentHash = new ConsistentHash();
        if (typeof options.vnodeNumber == "number") this._iVnodeNumber = options.vnodeNumber;
    }

    this._worker._objname = this._objname;
    this._initialize($ObjectName);

    this._registryCachePath = ''; // 主控缓存
    if (process.env.TAF_CONFIG) {
        var fileName = 'registry.tafdat';
        var that = this;
        if (this._comm && this._comm.getProperty('serverName')) {
            fileName = this._comm.getProperty('serverName') + '.tafdat';
        }
        this._registryCachePath = path.join(process.env.TAF_CONFIG, '../../data', fileName);

        try {
            var ret = fs.existsSync(this._registryCachePath);
            if (ret === false) {
                fs.writeFile(this._registryCachePath, JSON.stringify({}), function (err) {
                    if (err) {
                        console.error("create registry cache file error ", that._registryCachePath, err);
                        that._registryCachePath = "";
                    }
                });
            }
        } catch (e) { }
    }

    //console.log("EndpointManager constructor $ObjectName=", $ObjectName, ",_objname=", this._objname, ",_setname=", this._setname, ",_registryCachePath=", this._registryCachePath);
};

module.exports.EndpointManager = EndpointManager;

//设置registry缓存
EndpointManager.prototype._setRegistryCache = function (key, val) {
    var that = this;

    var deferred = Q.defer();
    var rsp = {
        iRet: 0,
        message: 'success'
    };

    var processId = process.env.PROCESS_INDEX || 0;
    //console.log(`set PROCESS_INDEX=${process.env.PROCESS_INDEX}, PROCESS_NUM=${process.env.PROCESS_NUM}, processId=${processId}`);
    if (processId != 0) {
        //只有编号为0的子进程才会写缓存到文件。
        return deferred.promise;
    }

    if (!key || !that._registryCachePath) {
        process.nextTick(function () {
            rsp.iRet = -1;
            rsp.message = 'setRegistryCache param invalid';
            deferred.resolve(rsp);
        });
        console.error("setRegistryCache param invalid", key, val, that._registryCachePath);
        return deferred.promise;
    }

    try {
        let data = fs.readFileSync(that._registryCachePath, 'utf-8');
        var t = new Date();
        var timeStr = (t.getYear() + 1900) + '-' + (t.getMonth() + 1) + '-' + t.getDate() + ' ' + t.getHours() + ':' + t.getMinutes() + ":" + t.getSeconds();

        var info = {
            modify: timeStr
        };

        try {
            if (data && data.length > 0) {
                info = JSON.parse(data);
                info.modify = timeStr;
            }
        } catch (e) {
            info = {
                modify: timeStr
            };
            console.error('JSON.parse exception path=', that._registryCachePath, ",data=", data, ",info=", info, ",error=", e)
        }

        try {
            info[key] = val;
            fs.writeFileSync(that._registryCachePath, JSON.stringify(info));
        } catch (e) {
            console.error("setRegistryCache fs.writeFile exception", that._registryCachePath, key, val, e);
            rsp.iRet = -1;
            rsp.message = 'setRegistryCache fs.writeFile exception';
            deferred.resolve(rsp);
        }
    } catch (e) {
        console.error("setRegistryCache fs.readFile exception", that._registryCachePath, key, val, e);
        rsp.iRet = -1;
        rsp.message = 'setRegistryCache fs.readFile exception';
        deferred.resolve(rsp);
    }

    return deferred.promise;
};

//从缓存中恢复registry数据
EndpointManager.prototype._getRegistryCache = function (key) {
    var info = {};
    var val = '';
    var that = this;
    var content = '';
    try {
        if (that._registryCachePath) {
            content = fs.readFileSync(that._registryCachePath, 'utf-8');
            info = JSON.parse(content);
            val = info[key] || '';
        }
    } catch (e) {
        val = '';
        console.error("getRegistryCache exception", key, that._registryCachePath, content, e);
    }

    return val;
}

//解析服务端名称，发现是否是直连端口
EndpointManager.prototype._initialize = function ($ObjectProxyName) {
    var options = $ObjectProxyName.split('@');
    if (options.length != 2) {
        return;
    }

    this._objname = options[0];
    this._worker._objname = this._objname;
    this._direct = true;
    var endpoints = options[1].split(":"), endpointInfoArr = [];
    for (var i = 0; i < endpoints.length; i++) {
        var endpoint = Endpoint.parse(endpoints[i]);
        this._addEndpoint(endpoint);
        endpointInfoArr.push({
            endpoint: endpoint,
            vNodeNumber: this._iVnodeNumber
        });
    }
    if (this._consistentHash) {
        this._consistentHash.addEndpoints(endpointInfoArr);
    }
};

EndpointManager.prototype.getAllAdapters = function () {
    return this._adapters || [];
};

EndpointManager.prototype._initConsistentHash = function () {
    var self = this;
    self._consistentHash = new ConsistentHash(); //todo? 对象创建时可能已经创建了ConsistentHash
    var endpointInfoArr = self._adapters.map(function (adapter) {
        return {
            endpoint: adapter.endpoint,
            vNodeNumber: self._iVnodeNumber
        }
    })
    if (endpointInfoArr.length) {
        self._consistentHash.addEndpoints(endpointInfoArr);
    }
};

EndpointManager.prototype._addEndpoint = function ($endpoint) {
    var adapter = new AdapterProxy();
    adapter.worker = this._worker;
    adapter.endpoint = $endpoint;
    adapter.initialize();

    this._adapters.push(adapter);
    return adapter;
};

EndpointManager.prototype._doEndpointsException = function (data) {
    if (data && data.response && data.response.error) {
        console.error("_doEndpointsException code=", data.response.error.code, ",server=", this._objname, " ,adapter.length=", this._adapters.length);
    } else {
        console.error("_doEndpointsException servant=", this._objname, ",adapter.length=", this._adapters.length);
    }
    this._bRequest = false;
    this._iRefreshTime = TimeProvider.nowTimestamp() + 2000; //频率控制：获取主控失败 2秒钟再更新

    this._recoverEndpoint();
};

//根据传入的协议、地址以及端口号查找是否已在列表中
EndpointManager.prototype._findEndpointByInfo = function ($endpoint) {
    for (var i = 0; i < this._adapters.length; i++) {
        var adapter = this._adapters[i];
        if (adapter._endpoint.sProtocol === $endpoint.sProtocol && adapter._endpoint.sHost === $endpoint.sHost && adapter._endpoint.iPort === $endpoint.iPort) {
            return adapter;
        }
    }

    return undefined;
};

EndpointManager.prototype._findEndpointByIpPort = function (ipPort) {
    for (var i = 0; i < this._adapters.length; i++) {
        var adapter = this._adapters[i];
        if (adapter._endpoint.sHost === ipPort.sHost && adapter._endpoint.iPort === ipPort.iPort) {
            return adapter;
        }
    }

    return undefined;
};

//主控异常时，恢复主控数据
EndpointManager.prototype._recoverEndpoint = function () {
    var endpoints = [];
    var endpointStr = this._getRegistryCache(this._objname);
    if (endpointStr) {
        endpoints = endpointStr.split(":");
    }

    var actives = [];

    if (endpoints.length > 0) {
        for (var i = 0; i < endpoints.length; i++) {
            actives.push(Endpoint.parse(endpoints[i]));
        }
    }

    if (actives.length > 0) {
        this._updateEndpoint(actives);
        this._worker.doInvoke();
    }

    console.error("[recoverEndpoint]", this._objname, ", ", actives.length, ", ", this._adapters.length, ", recover from cache");
};

//更新endpoint
EndpointManager.prototype._updateEndpoint = function (actives) {
    actives = actives || [];
    if (actives.length == 0) {
        console.error("[update endpoint]actives is empty!")
        return
    }

    //01 将新的节点接入到活动列表中
    var i = 0, newEndpoints = [], inactiveEndpoints = [], vNodeNumber = this._iVnodeNumber;
    for (i = 0; i < actives.length; i++) {
        var endpointItem = actives[i]
        if (this._findEndpointByInfo(endpointItem) === undefined) {
            //如果不在已有列表中，则新加入
            newEndpoints.push(endpointItem);
            this._addEndpoint(endpointItem);
        }
    }

    //02 将已经去除的地址，从活动列表中删除
    for (i = 0; i < this._adapters.length; i++) {
        var bFound = false;
        var endpoint = this._adapters[i]._endpoint;

        //查找该地址是否在活动列表中
        for (var ii = 0, len = actives.length; ii < len; ii++) {
            if (endpoint.sProtocol === actives[ii].sProtocol && endpoint.sHost === actives[ii].sHost && endpoint.iPort === actives[ii].iPort) {
                bFound = true;
                break;
            }
        }

        //如果在活动列表中没有找到，则说明该地址被停止了或者去除了，则从当前的队列中删除
        if (!bFound) {
            this._adapters[i].destroy();
            this._adapters.splice(i, 1);
            inactiveEndpoints.push(endpoint);
            //从hashring中删除
            if (this._consistentHash) {
                this._consistentHash.removeEndpoints([endpoint]);
            }
            i--;
        }
    }
    //将新的节点添加到一致性哈希
    newEndpoints = newEndpoints.map(function (endpoint) {
        return {
            endpoint: endpoint,
            vNodeNumber: vNodeNumber
        }
    })
    if (newEndpoints.length && this._consistentHash) {
        this._consistentHash.addEndpoints(newEndpoints);
    }
    //从一致性哈希中删除节点
    if (inactiveEndpoints.length && this._consistentHash) {
        this._consistentHash.removeEndpoints(inactiveEndpoints);
    }
    //每次adapter列表添加新成员之后sort一次，保证所有节点的adapter顺序一致，避免出现使用hashcode时节点仍然没有分发到同一节点的情况
    if (newEndpoints.length) {
        this._adapters.sort(function (adapter1, adapter2) {
            return adapter1.endpoint.sHost > adapter2.endpoint.sHost ? -1 : 1;
        });
    }

    if (newEndpoints.length > 0) {
        var vNewEndpointStr = []
        for (var j = 0; j < newEndpoints.length; j++) {
            var newEndpointItem = newEndpoints[j].endpoint
            vNewEndpointStr.push(newEndpointItem.toString())

        }
        console.log("[update endpoint]add endpoint", this._objname, vNewEndpointStr.join(":"))
    }

    if (inactiveEndpoints.length > 0) {
        var vInactiveEndpointStr = []
        for (var k = 0; k < inactiveEndpoints.length; k++) {
            var inactiveEndpointItem = inactiveEndpoints[k]
            vInactiveEndpointStr.push(inactiveEndpointItem.toString())

        }
        console.log("[update endpoint]remove endpoint", this._objname, vInactiveEndpointStr.join(":"))
    }
}

//请求主控的处理函数
EndpointManager.prototype._doEndpoints = function (result) { //如果请求主控服务成功
    if (result.response.return != 0) {
        console.error("[TAF][EndpointManager doEndpoints exception ,return=", result.response.return, ",objname=", this._objname, ",setname=", this._setname);
        return this._doEndpointsException();
    }
    var nowTime = TimeProvider.nowTimestamp();
    this._bRequest = false;

    //有回成功的结点，按照正常的频率更新
    //如果返回空列表，则不更新本地的节点列表 10s刷新一次
    if (result.response.arguments.activeEp.value.length == 0) {
        this._iRefreshTime = nowTime + this._iActiveEmptyInterval;
        console.error("[TAF][EndpointManager doEndpoints, callback activeEps is empty,objname=", this._objname, ",setname=", this._setname);
        return;
    } else {
        this._iRefreshTime = nowTime + this._iRefreshInterval;
    }

    var actives = [], vEndpointStr = [];
    var endpoints = result.response.arguments.activeEp;
    for (var i = 0, len = endpoints.value.length; i < len; i++) {
        var newEndpoint = new Endpoint();
        newEndpoint.sProtocol = endpoints.value[i].istcp ? "tcp" : "udp";
        newEndpoint.sHost = endpoints.value[i].host;
        newEndpoint.iPort = endpoints.value[i].port;
        newEndpoint.iTimeout = endpoints.value[i].timeout || 0;
        newEndpoint.setId = endpoints.value[i].setId || '';
        newEndpoint.containerName = endpoints.value[i].containerName || '';
        actives.push(newEndpoint);
        vEndpointStr.push(newEndpoint.toString());
    }

    //缓存registry数据
    this._setRegistryCache(this._objname, vEndpointStr.join(":"));

    //更新endpoint
    this._updateEndpoint(actives);

    //通知对应的ObjectProxy可以发送缓存中的请求了
    this._worker.doInvoke();
}

//非直连的情况下，到主控查询活动列表
EndpointManager.prototype._dns = function () {
    var nowTime = TimeProvider.nowTimestamp();

    //01 先判断是否可以查主控
    if (this._direct) { //如果是直连，不查主控
        return;
    }
    if (this._bRequest && this._iRequestTimeout < nowTime) { //如果正在请求中，但已经超时，则重置
        console.error("[TAF][EndpointManager doEndpoints, requesting but timeout ,objname=", this._objname, ",setname=", this._setname);
        this._doEndpointsException();
    }
    if (this._bRequest || this._iRefreshTime > nowTime) { //如果正在请求，或者还没到重试时间
        return;
    }

    //02 根据是否开起SET化查询不同的活动IPList
    this._bRequest = true;
    this._iRequestTimeout = nowTime + this._iWaitTime;
    var locator = this._comm.getProperty("locator");
    if (!this._locator) {
        //第一次加载主控
        this._locator = locator;
        this._registry.setLocator(locator);
    } else {
        //非首次加载主控
        if (locator != undefined && locator != "" && this._locator != locator) {
            //主控发生改变
            console.log('[locator change] [old]' + this._locator + ' [new] ' + locator);
            this._locator = locator;
            this._registry.resetLocator(locator);
        }
    }

    if (this._comm.ClientConfig.SetOpen && (this._setname || this._comm.ClientConfig.SetDivision)) {
        this._registry.findObjectByIdInSameSet(this._objname, this._setname || this._comm.ClientConfig.SetDivision).then(this._doEndpoints.bind(this), this._doEndpointsException.bind(this));
    } else {
        this._registry.findObjectByIdInSameGroup(this._objname).then(this._doEndpoints.bind(this), this._doEndpointsException.bind(this));
    }
};

//按照一定的规则选取一个可用的服务连接
EndpointManager.prototype.selectAdapterProxy = function (reqMessage) {

    //01 如果是非直连，则进入请求主控处理逻辑
    !this._direct && this._dns();

    //若当前节点列表为空，直接返回
    if (!this._adapters || this._adapters.length == 0) return;

    //02 hashcode 调用
    var adapter, adapters = [];
    var hashCode = +reqMessage.request.property['hashCode'];
    var consistentHash = reqMessage.request.property['consistentHash'];
    var useHashCode = ("undefined" !== typeof consistentHash) || (hashCode && !isNaN(hashCode));
    adapters = this._adapters.slice(0);

    if (useHashCode) {
        if ("undefined" !== typeof consistentHash) {
            //一致性哈希
            if (!this._consistentHash) this._initConsistentHash();
            var endpoints = this._consistentHash.getEndPoints(consistentHash, adapters.length, true), firstHashAdapter;
            do {
                var endpoint = endpoints[0];
                adapter = this._findEndpointByIpPort(endpoint);
                if (!adapter) {
                    endpoints.splice(0, 1);
                    continue;
                }
                if (adapter.checkActive()) {
                    return adapter;
                }
                endpoints.splice(0, 1);
                if (!firstHashAdapter) firstHashAdapter = adapter;
            } while (endpoints.length > 0);
            adapter = firstHashAdapter;
        } else {
            //取模哈希
            var hash;
            do {
                hash = hashCode % adapters.length;
                adapter = adapters[hash];
                if (adapter.checkActive()) {
                    return adapter;
                }
                adapters.splice(hash, 1);
            } while (adapters.length > 0);

            for (var i = 0; i < this._adapters.length; i++) {
                if (this._adapters[i].connExc == false) {
                    adapters.push(this._adapters[i]);
                }
            }
            hash = hashCode % adapters.length;
            adapter = adapters[hash];
        }
        //hash没有找到active的adapter时，强制连接，并且把请求强制塞进去
        adapter.checkActive(true);
        adapter.invoke(reqMessage);
        //console.error("[selectAdapterProxy]hash ", this._objname, ",adapters.size=" ,this._adapters.length, ", select no adapter]");
        return;
    }

    // 03 检查是否有可用的连接
    for (var i = 0; i < this._adapters.length; i++) {
        adapter = this._adapters[(this._hash++) % this._adapters.length];
        if (adapter.checkActive()) {
            return adapter;
        }
    }

    // 如果当前没有可用的连接，则随机选取一个
    adapter = this._adapters[(this._hash++) % this._adapters.length];
    adapter.checkActive(true); //强制连接
    //console.error("[selectAdapterProxy]no hash servant：", this._objname, ",adapter.length=" ,this._adapters.length, ", select no adapter");

    return;
};

EndpointManager.prototype.doFinishInvoke = function (endpoint, iResultCode) {
    var adapter = this._findEndpointByInfo(endpoint);
    if (adapter) {
        adapter._doFinishInvoke(iResultCode);
    }
}

//销毁
EndpointManager.prototype.destroy = function () {
    for (var i = 0; i < this._adapters.length; i++) {
        this._adapters[i].destroy();
    }
    if (this._consistentHash) {
        this._consistentHash.destroy();
    }
};
